import{_ as t,o,c as a,a5 as r}from"./chunks/framework.PLGyiLjE.js";const d=JSON.parse('{"title":"Your first steps","description":"","frontmatter":{},"headers":[],"relativePath":"guides/first-steps.md","filePath":"guides/first-steps.md"}'),s={name:"guides/first-steps.md"};function n(i,e,h,g,l,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="your-first-steps" tabindex="-1">Your first steps <a class="header-anchor" href="#your-first-steps" aria-label="Permalink to &quot;Your first steps&quot;">​</a></h1><h2 id="_1-whose-thread-is-this" tabindex="-1">1. Whose thread is this? <a class="header-anchor" href="#_1-whose-thread-is-this" aria-label="Permalink to &quot;1. Whose thread is this?&quot;">​</a></h2><p>Pick a class (Trailguard, Wayfinder, Runehand or Shadehand), one of its two paths and <strong>Girl</strong> or <strong>Boy</strong>. Your path is the one you grow into at level 30, so pick the one you like best. You can make more fighters later.</p><h2 id="_2-name-and-keys" tabindex="-1">2. Name and keys <a class="header-anchor" href="#_2-name-and-keys" aria-label="Permalink to &quot;2. Name and keys&quot;">​</a></h2><p>On <strong>Name your hero</strong>, type a name (2–18 letters, numbers, spaces or simple punctuation; the dice picks one for you) and press <strong>Begin</strong>. Pick <strong>Arrow keys</strong> or <strong>WASD</strong> on the <strong>Choose your keys</strong> card. You can change it later in <strong>Settings → Keys</strong>.</p><h2 id="_3-a-champion-s-memory" tabindex="-1">3. A champion&#39;s memory <a class="header-anchor" href="#_3-a-champion-s-memory" aria-label="Permalink to &quot;3. A champion&#39;s memory&quot;">​</a></h2><p>Next you play as a champion of your path at <strong>Lv 50</strong>. Fight through <strong>The Cliffs at Gullcry</strong> and <strong>The Crown Chimney</strong> to <strong>Sir Lackluster</strong>... and lose. That&#39;s the story: he pulls your thread loose. It costs you nothing.</p><h2 id="_4-loomhaven" tabindex="-1">4. Loomhaven <a class="header-anchor" href="#_4-loomhaven" aria-label="Permalink to &quot;4. Loomhaven&quot;">​</a></h2><p>You wake on the Mending Green in Loomhaven at <strong>Lv 1</strong>, with the title <strong>Loose End</strong>. More stands open in town as you clear stages.</p><h2 id="_5-the-stage-gate" tabindex="-1">5. The Stage Gate <a class="header-anchor" href="#_5-the-stage-gate" aria-label="Permalink to &quot;5. The Stage Gate&quot;">​</a></h2><p>The Stage Gate is your only road out of town. Press <strong>Open Stage Gate</strong> on the first card, or walk to the glowing gate and press your use key (<strong>Z</strong>, or <strong>G</strong> with WASD). The chapter map opens on <strong>1-1 Water Gate Steps</strong>.</p><h2 id="_6-your-first-run" tabindex="-1">6. Your first run <a class="header-anchor" href="#_6-your-first-run" aria-label="Permalink to &quot;6. Your first run&quot;">​</a></h2><p>Move, jump and attack your way through each screen. When you see a hint about skills, open <strong>Pause → Combo list</strong> to see every combo. Each stage has 3 stars: clear it, beat the time, and hit the combo goal.</p><h2 id="_7-your-first-weapon" tabindex="-1">7. Your first weapon <a class="header-anchor" href="#_7-your-first-weapon" aria-label="Permalink to &quot;7. Your first weapon&quot;">​</a></h2><p>Clearing 1-1 opens the <strong>Forge</strong>. Your first forged weapon is at least Rare, and you&#39;ll feel the difference right away. Then press <strong>Continue to 1-2</strong>.</p><p><strong>Miss being powerful?</strong> The <strong>Relive the memory</strong> sign in Loomhaven replays the champion stages, or lets you try any of the eight champions. Nothing is paid or lost.</p>',16)])])}const c=t(s,[["render",n]]);export{d as __pageData,c as default};
